const choice = (id: string, prompt: string, options: string[], answer: number, feedback: string[], concept: string, hint: string, sentence?: string): ChoiceQuestion => ({ id, kind: 'choice', prompt, options, answer, feedback, concept, hint, explanation: feedback[answer]!, ...(sentence ? { sentence } : {}) });
const order = (id: string, prompt: string, tokens: string[], accept: string[], concept: string, hint: string, explanation: string): OrderQuestion => ({ id, kind: 'order', prompt, tokens, accept, concept, hint, explanation });
const section = (title: string, paragraphs: string[], sentence: string, analysis: string, pitfall: string, takeaway: string): LessonSection => ({ title, paragraphs, examples: [{ sentence, analysis }], pitfall, takeaway });
const source = (bookId: BookId, section: string, note: string) => ({ bookId, section, note });

